const crypto = require('crypto');

function hashPassword(password, salt) {
  return crypto.createHash('sha256').update(salt + password).digest('hex');
}

function generateSalt() {
  return crypto.randomBytes(16).toString('hex');
}

function generateToken() {
  return crypto.randomUUID();
}

function tokenExpires(hours = 24) {
  return new Date(Date.now() + hours * 3600000).toISOString();
}

function isExpired(isoDate) {
  if (!isoDate) return true;
  return new Date(isoDate) < new Date();
}

function isValidEmail(email) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

function isValidTime(time) {
  return /^([01]?\d|2[0-3]):[0-5]\d$/.test(time);
}

function isValidUsername(name) {
  return /^[a-zA-Z0-9_]{3,20}$/.test(name);
}

function isStrongPassword(pwd) {
  return pwd.length >= 8 && /[A-Za-z]/.test(pwd) && /\d/.test(pwd);
}


const input = $input.first().json;
const username = (input.username || '').trim();
const password = input.password || '';
const email = (input.email || '').trim();
const interests = (input.interests || '').trim();
const schedule_time = (input.schedule_time || '').trim();

if (!isValidUsername(username)) {
  return { json: { success: false, error: 'Nom d\'utilisateur invalide.' } };
}
if (!isStrongPassword(password)) {
  return { json: { success: false, error: 'Mot de passe trop faible.' } };
}
if (!isValidEmail(email)) {
  return { json: { success: false, error: 'Email invalide.' } };
}

const salt = generateSalt();
const passwordHash = hashPassword(password, salt);
const sessionToken = generateToken();
const expiresAt = tokenExpires(24);
const now = new Date().toISOString();

return {
  json: {
    _insert: true,
    username,
    password_hash: passwordHash,
    salt,
    email,
    interests,
    schedule_time,
    active: true,
    session_token: sessionToken,
    session_expires_at: expiresAt,
    gdpr_consent_at: now,
    created_at: now,
    success: true,
    sessionToken,
    userId: username,
    error: null
  }
};

const newUser = $('Prepare User').first().json;
const rows = $input.all().map(i => i.json);
const exists = rows.some(r => (r.username || '').toLowerCase() === newUser.username.toLowerCase());
if (exists) {
  return { json: { success: false, error: 'Ce nom d\'utilisateur existe déjà.', _insert: false } };
}
return { json: newUser };
